// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address that will attempt to call setOwner and the newOwner address to set
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful, but otherwise wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // admin is the deployer set in setUp(); that's address(this) at deployment time in setUp()
        address admin = address(this);

        // ensure we consider the scenario where caller is owner but not admin and when caller is not owner
        // First, read initial owner (should be the deployer of C in setUp())
        address initialOwner = c.owner();

        // The general property: only admin can call setOwner. So if caller != admin, call should revert / fail.
        // We execute the call as the fuzzed caller and catch whether it succeeded.
        bool ok;
        try c.setOwner(newOwner) {
            // if executed directly here, it's from this test contract (admin) — but we need to simulate call from caller
            // So instead we use vm.prank to impersonate caller and call setOwner, catching revert via low-level try/catch
            // Reset ok since this path is not used
            ok = true;
        } catch {
            ok = false;
        }

        // Now perform the real attempted call as the fuzzed caller via vm.prank and capture success via try/catch
        bool callSucceeded;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // After the attempt, read the owner
        address finalOwner = c.owner();

        // The invariant to assert: if caller is not the admin (deployer), then setOwner must NOT succeed and owner must remain unchanged.
        // This holds for the reference contract for all inputs, but the mutant (which permits owner to act as admin) will allow the call when
        // caller == initialOwner and initialOwner != admin, changing owner — thus breaking this assertion for some inputs.
        if (caller != admin) {
            // require that the call did not succeed and owner unchanged
            assertTrue(!callSucceeded && finalOwner == initialOwner);
        } else {
            // when caller == admin, the call is allowed; owner should have been updated
            assertTrue(callSucceeded && finalOwner == newOwner);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller is the address that will attempt to call setOwner;
    // newOwner is the address passed into setOwner.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep inputs broad but avoid the trivial case where caller is the deployer (admin)
        // because the reference allows the deployer to call setOwner legitimately.
        // We want to assert that when caller != deployer, calling setOwner as caller
        // does NOT change owner under the reference implementation.
        address deployer = address(this);

        vm.assume(caller != deployer);

        // Record owner before the attempted call
        address ownerBefore = c.owner();

        // Have the fuzzed caller attempt to call setOwner(newOwner)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // After the attempted call, read owner
        address ownerAfter = c.owner();

        // GENERAL RULE (one assert): For any caller != deployer, the reference C will NOT allow that caller
        // to change owner; therefore ownerAfter must equal ownerBefore for all admissible inputs.
        // The mutant (which checks owner instead of admin in onlyAdmin) will allow the current owner
        // (when owner != deployer) to call setOwner and change owner, causing this assertion to fail
        // for some fuzzed inputs. We perform no other assertions.
        assertTrue(ownerAfter == ownerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller tries to call setOwner with newOwner
    // We must allow the fuzzer to pick addresses; keep admissible domain wide
    function testFuzz_property(address caller, address newOwner) public {
        // Avoid trivial zero-address newOwner to keep domain wide but sensible
        // (still allow zero if fuzzer picks it)
        // Ensure caller is not the deployer (admin) in many cases so we can detect mutant
        address admin = address(this); // setUp deployer

        // Make caller have some ETH so that vm.prank can act as them (not strictly necessary but harmless)
        vm.deal(caller, 1 ether);

        // Record owner before the attempted call
        address ownerBefore = c.owner();

        // The reference requires only admin can call setOwner; so if caller != admin,
        // then the call should not change owner. We will attempt the call and ignore revert (capture success).
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // After the call attempt, read owner
        address ownerAfter = c.owner();

        // General invariant (single assert): In the correct contract, any caller who is NOT the deployer
        // cannot change owner: ownerAfter == ownerBefore whenever caller != admin.
        // This is a universal property the reference satisfies for all inputs; the mutant (which lets owner call)
        // will violate it for inputs where caller equals current owner and owner != admin.
        if (caller != admin) {
            assertTrue(ownerAfter == ownerBefore);
        } else {
            // If caller == admin, reference allows change — then after successful call owner should be newOwner
            // (we still must use a single assert across all branches; we implement it by composing a boolean)
            // Consolidate into single boolean for assertTrue below
            assertTrue(ownerAfter == (ok ? newOwner : ownerBefore));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the newOwner and an address that will act as admin (the deployer is admin by constructor)
    function testFuzz_property(address potentialNewOwner) public {
        // Keep the fuzzed address wide but non-zero to be meaningful as an owner
        vm.assume(potentialNewOwner != address(0));

        // The reference contract C sets owner in constructor to the deployer (this test contract)
        // We call setOwner as that deployer (admin) using vm.prank to be msg.sender == admin
        // Use address(this) because setUp deployed C from this same contract
        bool ok;
        vm.prank(address(this));
        try c.setOwner(potentialNewOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // GENERAL RULE: In the correct contract, any successful call to setOwner by admin returns true.
        // We assert that the call we just made returned true (ok == true). The mutant that flips/zeros admin
        // inside onlyAdmin can alter subsequent observable behavior; the fuzzer will find inputs where
        // behavior diverges across versions because the reference always returns true here for any input.
        assertTrue(ok);
    }
}
